line-length = 120\nsrc = [\"src\", \"tests\"]\n\n[tool.ruff.lint]\nselect = [\n    \"E\", \"W\",  # pycodestyle\n    \"F\",       # pyflakes\n    \"I\",       # isort\n    \"UP\",      # pyupgrade\n    \"B\",       # flake8-bugbear\n    \"C4\",      # flake8-comprehensions\n    \"SIM\",     # flake8-simplify\n    \"PIE\",     # flake8-pie\n    \"PGH\",     # pygrep-hooks\n    \"RUF\",     # ruff-specific\n    \"T20\",     # flake8-print\n    \"PERF\",    # perflint\n]\nignore = [\n    \"E501\",    # line length handled by formatter\n]\n\n[tool.ruff.lint.isort]\nknown-first-party = [\"memsearch\"]\n\n[tool.ruff.lint.per-file-ignores]\n\"tests/*\" = [\"T20\"]      # allow print in tests\n\"examples/*\" = [\"T20\"]   # allow print in examples\n\n[tool.coverage.run]\nsource = [\"memsearch\"]\n\n[tool.coverage.report]\nshow_missing = true\nskip_empty = true\n"
